64	// OnChange ensures a Role Binding exists in every project namespace to the RoleTemplate ClusterRole.
65	// If there are promoted rules, it creates a second Role Binding in each namespace to the promoted ClusterRole
66	func (p *prtbHandler) OnChange(_ string, prtb *v3.ProjectRoleTemplateBinding) (*v3.ProjectRoleTemplateBinding, error) {
67		if prtb == nil || prtb.DeletionTimestamp != nil || !features.AggregatedRoleTemplates.Enabled() {
68			return nil, nil
69		}
70	
71		// Only run this controller if the PRTB is for this cluster
72		clusterName, _ := rbac.GetClusterAndProjectNameFromPRTB(prtb)
73		if clusterName != p.clusterName {
74			return nil, nil
75		}
76	
77		// Create bindings
78		if err := errors.Join(p.reconcileClusterRoleBindings(prtb), p.reconcileBindings(prtb)); err != nil {
79			return nil, err
80		}
81	
82		// Ensure a service account impersonator exists on the cluster.
83		if prtb.UserName != "" {
84			if err := p.impersonationHandler.ensureServiceAccountImpersonator(prtb.UserName); err != nil {
85				return nil, fmt.Errorf("error ensuring service account impersonator for %s: %w", prtb.UserName, err)
86			}
87		}
88	
89		return prtb, nil
90	}
