171			crb, err := rbac.BuildAggregatingClusterRoleBindingFromRTB(prtb, promotedRuleName)
172			if err != nil {
173				return err
174			}
175			crbs = append(crbs, crb)
176		}
177	
178		// Namespace rules always need to be created.
179		namespaceCRBs, err := p.buildNamespaceBindings(prtb)
