83	// reconcileBindings builds and creates ClusterRoleBinding for CRTB and removes any CRBs that shouldn't exist.
84	func (c *crtbHandler) reconcileBindings(crtb *v3.ClusterRoleTemplateBinding, remoteConditions *[]metav1.Condition) error {
85		condition := metav1.Condition{Type: reconcileClusterRoleBindings}
86	
87		isExternal, err := isRoleTemplateExternal(crtb.RoleTemplateName, c.rtClient)
88		if err != nil {
89			c.s.AddCondition(remoteConditions, condition, failureToGetRoleTemplate, err)
90			return err
91		}
92	
93		var roleName string
94		if isExternal {
95			roleName = crtb.RoleTemplateName
96		} else {
97			roleName = rbac.AggregatedClusterRoleNameFor(crtb.RoleTemplateName)
98		}
99	
100		crb, err := rbac.BuildClusterRoleBindingFromRTB(crtb, roleName)
101		if err != nil {
102			c.s.AddCondition(remoteConditions, condition, failureToBuildClusterRoleBinding, err)
103			return err
104		}
105	
106		aggregationCRBs, err := c.crbClient.List(metav1.ListOptions{LabelSelector: rbac.GetCRTBOwnerLabel(crtb.Name)})
107		if err != nil || aggregationCRBs == nil {
108			c.s.AddCondition(remoteConditions, condition, failureToListClusterRoleBindings, err)
109			return err
110		}
111	
112		// Delete any ClusterRoleBindings that were created for this CRTB before the aggregation changes.
113		// TODO: Remove this once roletemplate aggregation is the only enabled RBAC model. https://github.com/rancher/rancher/issues/53743
114		legacyCRBs, err := c.crbClient.List(metav1.ListOptions{LabelSelector: rtbOwnerLabel + "=" + rbac.GetRTBLabel(crtb.ObjectMeta)})
115		if err != nil || legacyCRBs == nil {
116			c.s.AddCondition(remoteConditions, condition, failureToListClusterRoleBindings, err)
117			return err
118		}
119	
120		currentCRBs := append(aggregationCRBs.Items, legacyCRBs.Items...)
121	
122		// Find if the required CRB that already exists and delete all excess CRBs.
123		// There should only ever be 1 cluster role binding per CRTB.
124		var matchingCRB *rbacv1.ClusterRoleBinding
125		for _, currentCRB := range currentCRBs {
126			if rbac.IsClusterRoleBindingContentSame(crb, &currentCRB) && matchingCRB == nil {
127				matchingCRB = &currentCRB
128				continue
129			}
130			if err := rbac.DeleteResource(currentCRB.Name, c.crbClient); err != nil {
131				c.s.AddCondition(remoteConditions, condition, failureToDeleteClusterRoleBinding, err)
132				return err
133			}
134		}
135	
136		// If we didn't find an existing CRB, create it.
137		if matchingCRB == nil {
138			if crb.Labels == nil {
139				crb.Labels = map[string]string{}
140			}
141			crb.Labels[rbac.AggregationFeatureLabel] = "true"
142			if _, err := c.crbClient.Create(crb); err != nil {
143				c.s.AddCondition(remoteConditions, condition, failureToCreateClusterRoleBinding, err)
144				return fmt.Errorf("failed to create cluster role binding %s: %w", crb.Name, err)
145			}
146		}
147		c.s.AddCondition(remoteConditions, condition, clusterRoleBindingExists, nil)
148		return nil
149	}
150	
151	var timeNow = func() time.Time {
152		return time.Now()
153	}
154	
155	func (c *crtbHandler) updateStatus(crtb *v3.ClusterRoleTemplateBinding, remoteConditions []metav1.Condition) error {
156		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
157			crtbFromCluster, err := c.crtbCache.Get(crtb.Namespace, crtb.Name)
158			if err != nil {
159				return err
160			}
161			if status.CompareConditions(crtbFromCluster.Status.RemoteConditions, remoteConditions) {
162				return nil
163			}
164	
165			crtbFromCluster.Status.SummaryRemote = status.SummaryCompleted
166			if crtbFromCluster.Status.SummaryLocal == status.SummaryCompleted {
167				crtbFromCluster.Status.Summary = status.SummaryCompleted
168			}
169			for _, c := range remoteConditions {
170				if c.Status != metav1.ConditionTrue {
171					crtbFromCluster.Status.Summary = status.SummaryError
172					crtbFromCluster.Status.SummaryRemote = status.SummaryError
173					break
174				}
175			}
176	
177			crtbFromCluster.Status.LastUpdateTime = timeNow().Format(time.RFC3339)
178			crtbFromCluster.Status.ObservedGenerationRemote = crtb.ObjectMeta.Generation
179			crtbFromCluster.Status.RemoteConditions = remoteConditions
180			_, err = c.crtbClient.UpdateStatus(crtbFromCluster)
181			if err != nil {
182				return err
183			}
184			return nil
185		})
186	}
