27	type roleTemplateHandler struct {
28		crController crbacv1.ClusterRoleController
29	}
30	
31	// OnChange ensures that the following Cluster Roles exist:
32	//  1. A ClusterRole with the same name as the RoleTemplate (unless RoleTemplate is External)
33	//  2. An Aggregating ClusterRole that aggregates all inherited RoleTemplates with the name "RoleTemplateName-aggregator"
34	//
35	// For RoleTemplates with the Context == "Project", the additional cluster roles are created:
36	//  1. If the RoleTemplate has any rules for Global Resources, make a ClusterRole with those named "RoleTemplateName-promoted"
37	//  2. An Aggregating ClusterRole that aggregates all inherited RoleTemplates' promoted Cluster Roles named "RoleTemplateName-promoted-aggregator"
38	func (rth *roleTemplateHandler) OnChange(_ string, rt *v3.RoleTemplate) (*v3.RoleTemplate, error) {
39		if rt == nil || rt.DeletionTimestamp != nil || !features.AggregatedRoleTemplates.Enabled() {
40			return nil, nil
41		}
42	
43		clusterRoles, err := rth.clusterRolesForRoleTemplate(rt)
44		if err != nil {
45			return nil, err
46		}
47	
48		if err := rth.ensureOnlyDesiredClusterRolesExist(rt, clusterRoles); err != nil {
49			return nil, err
50		}
51	
52		// add aggregation label to external cluster role
53		if err := rth.addLabelToExternalRole(rt); err != nil {
54			return nil, err
55		}
56	
57		return rt, nil
58	}
59	
60	// ensureOnlyDesiredClusterRolesExist ensures that only the given list of Cluster Roles exist for the RoleTemplate.
61	func (rth *roleTemplateHandler) ensureOnlyDesiredClusterRolesExist(rt *v3.RoleTemplate, desiredCRs []*rbacv1.ClusterRole) error {
62		// ensure only desired Cluster Roles exist
63		desiredCRNames := make(map[string]any)
64		for _, cr := range desiredCRs {
65			desiredCRNames[cr.Name] = nil
66		}
67	
68		// get all existing Cluster Roles using the RoleTemplate owner label
69		currentCRs, err := rth.crController.List(metav1.ListOptions{LabelSelector: rbac.GetClusterRoleOwnerLabel(rt.Name)})
70		if err != nil {
71			return fmt.Errorf("failed to list cluster roles for role template %s: %w", rt.Name, err)
72		}
73		for _, currentCR := range currentCRs.Items {
74			if _, ok := desiredCRNames[currentCR.Name]; !ok {
75				// This ClusterRole is not part of the desired Cluster Role list, delete it
76				if err := rbac.DeleteResource(currentCR.Name, rth.crController); err != nil {
77					return fmt.Errorf("failed to delete cluster role %s: %w", currentCR.Name, err)
78				}
79			}
80		}
81	
82		// Make sure the desired Cluster Roles exist and have the right contents
83		for _, cr := range desiredCRs {
84			if err := rbac.CreateOrUpdateResource(cr, rth.crController, rbac.AreClusterRolesSame); err != nil {
85				return fmt.Errorf("failed to create or update cluster role %s: %w", cr.Name, err)
86			}
87		}
88		return nil
89	}
90	
91	// clusterRolesForRoleTemplate builds and returns all needed Cluster Roles for the RoleTemplate using the given rules.
92	func (rth *roleTemplateHandler) clusterRolesForRoleTemplate(rt *v3.RoleTemplate) ([]*rbacv1.ClusterRole, error) {
93		res := []*rbacv1.ClusterRole{}
94		// We extract the promoted rules from the RoleTemplate, so we don't want to modify the original object
95		rtCopy := rt.DeepCopy()
96	
97		if rtCopy.Context == projectContext {
98			// ClusterRoles for promoted rules
99			var promotedClusterRoles []*rbacv1.ClusterRole
100			var err error
101			promotedClusterRoles, err = rth.buildPromotedClusterRoles(rt)
102			if err != nil {
103				return nil, err
104			}
105	
106			res = append(res, promotedClusterRoles...)
107		}
108	
109		// If the RoleTemplate refers to an external cluster role, don't modify/create it. Instead we will aggregate it.
110		if !rtCopy.External {
111			res = append(res, rbac.BuildClusterRole(rbac.ClusterRoleNameFor(rtCopy.Name), rtCopy.Name, rtCopy.Rules))
112		}
113		res = append(res, rbac.BuildAggregatingClusterRole(rtCopy, rbac.ClusterRoleNameFor))
114	
115		return res, nil
116	}
