59	// OnChange creates all management plane cluster roles that will be needed. If there are no management plane rules in the role template, no cluster roles will be created.
60	func (r *roleTemplateHandler) OnChange(_ string, rt *v3.RoleTemplate) (*v3.RoleTemplate, error) {
61		if rt == nil || rt.DeletionTimestamp != nil {
62			return nil, nil
63		}
