96	// reconcileClusterRoles is responsible for ensuring the right set of Cluster Roles exist. It deletes any owned by the Role Template that shouldn't exist.
97	func (r *roleTemplateHandler) reconcileClusterRoles(rt *v3.RoleTemplate) error {
98		rules, err := r.gatherRules(rt)
99		if err != nil {
100			return err
101		}
102	
103		desiredCRs, err := r.buildClusterRoles(rt, rules)
104		if err != nil {
105			return err
106		}
107		addOwnerReferenceToClusterRole(desiredCRs, rt)
108	
109		currentCRs, err := r.crController.List(metav1.ListOptions{LabelSelector: rbac.GetClusterRoleOwnerLabel(rt.Name)})
110		if err != nil {
111			return err
112		}
113	
114		// We want to keep desired Cluster Roles from this handler and the Cluster Roles created by the handler in
115		// pkg/controllers/managementuser/rbac/roletemplates/roletemplate_handler.go
116		// These are:
117		//	- Base Cluster Role
118		//  - Aggregating Cluster Role
119		//  - Promoted Cluster Role
120		//  - Aggregating Promoted Cluster Role
121		desiredCRNames := []string{
122			rt.Name,
123			rbac.AggregatedClusterRoleNameFor(rt.Name),
124			rbac.PromotedClusterRoleNameFor(rt.Name),
125			rbac.AggregatedClusterRoleNameFor(rbac.PromotedClusterRoleNameFor(rt.Name)),
126		}
127		for _, desiredCR := range desiredCRs {
128			desiredCRNames = append(desiredCRNames, desiredCR.Name)
129		}
130	
131		var returnedError error
132		// Remove any Cluster Roles owned by this RoleTemplate that should not exist
133		for _, currentCR := range currentCRs.Items {
134			if !slices.Contains(desiredCRNames, currentCR.Name) {
135				if err := rbac.DeleteResource(currentCR.Name, r.crController); err != nil {
136					returnedError = errors.Join(returnedError, err)
137				}
138			}
139		}
140	
141		// Create or update the desired CRs
142		for _, cr := range desiredCRs {
143			if err := rbac.CreateOrUpdateResource(cr, r.crController, rbac.AreClusterRolesSame); err != nil {
144				returnedError = errors.Join(returnedError, err)
145			}
146		}
147		return returnedError
148	}
